28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    private String postcode;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "membership_number")
72	    private String membershipNumber;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private Boolean bulkSignupWarning;
76	
77	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
78	    private Set<Pet> pets;
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    public String getPostcode() {
97	        return this.postcode;
98	    }
99	
100	    public void setPostcode(String postcode) {
101	        this.postcode = postcode;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    public String getEmail() {
113	        return this.email;
114	    }
115	
116	    public void setEmail(String email) {
117	        this.email = email;
118	    }
119	
120	    public LocalDate getRegistrationDate() {
121	        return this.registrationDate;
122	    }
123	
124	    public void setRegistrationDate(LocalDate registrationDate) {
125	        this.registrationDate = registrationDate;
126	    }
127	
128	    public String getCustomerCode() {
129	        return this.customerCode;
130	    }
131	
132	    public void setCustomerCode(String customerCode) {
133	        this.customerCode = customerCode;
134	    }
135	
136	    public String getHouseholdId() {
137	        return this.householdId;
138	    }
139	
140	    public void setHouseholdId(String householdId) {
141	        this.householdId = householdId;
142	    }
143	
144	    public Integer getNamesakeCount() {
145	        return this.namesakeCount;
146	    }
147	
148	    public void setNamesakeCount(Integer namesakeCount) {
149	        this.namesakeCount = namesakeCount;
150	    }
151	
152	    public String getMembershipNumber() {
153	        return this.membershipNumber;
154	    }
155	
156	    public void setMembershipNumber(String membershipNumber) {
157	        this.membershipNumber = membershipNumber;
158	    }
159	
160	    public Boolean getBulkSignupWarning() {
161	        return this.bulkSignupWarning;
162	    }
163	
164	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
165	        this.bulkSignupWarning = bulkSignupWarning;
166	    }
167	
168	    protected Set<Pet> getPetsInternal() {
169	        if (this.pets == null) {
170	            this.pets = new HashSet<>();
171	        }
172	        return this.pets;
173	    }
174	
175	    protected void setPetsInternal(Set<Pet> pets) {
176	        this.pets = pets;
177	    }
178	
179	    public List<Pet> getPets() {
180	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
181	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
182	        return Collections.unmodifiableList(sortedPets);
183	    }
184	
185	    public void setPets(List<Pet> pets) {
186	        this.pets = new HashSet<>(pets);
187	    }
188	
189	    public void addPet(Pet pet) {
190	        getPetsInternal().add(pet);
191	        pet.setOwner(this);
192	    }
193	
194	    /**
195	     * Return the Pet with the given name, or null if none found for this Owner.
196	     *
197	     * @param name to test
198	     * @return true if pet name is already in use
199	     */
200	    public Pet getPet(String name) {
201	        return getPet(name, false);
202	    }
203	
204	    /**
205	     * Return the Pet with the given name, or null if none found for this Owner.
206	     *
207	     * @param name to test
208	     * @return true if pet name is already in use
209	     */
210	    public Pet getPet(String name, boolean ignoreNew) {
211	        name = name.toLowerCase();
212	        for (Pet pet : getPetsInternal()) {
213	            if (!ignoreNew || !pet.isNew()) {
214	                String compName = pet.getName();
215	                compName = compName.toLowerCase();
216	                if (compName.equals(name)) {
217	                    return pet;
218	                }
219	            }
220	        }
221	        return null;
222	    }
223	
224	    public Pet getPet(Integer petId) {
225	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
226	    }
227	
228	    @Override
229	    public String toString() {
230	        return new ToStringCreator(this)
231	
232	            .append("id", this.getId())
233	            .append("new", this.isNew())
234	            .append("lastName", this.getLastName())
235	            .append("firstName", this.getFirstName())
236	            .append("address", this.address)
237	            .append("city", this.city)
238	            .append("telephone", this.telephone)
239	            .append("email", this.email)
240	            .toString();
241	    }
242	}
